<script>
(() => {
    const form = document.querySelector('[data-ajax-kpi]');
    if (!form || !window.fetch) return;
    form.addEventListener('submit', async (event) => {
        event.preventDefault();
        const button = form.querySelector('button[type="submit"]');
        const feedback = form.querySelector('.social-kpi-feedback');
        const initialLabel = button ? button.textContent : '';
        if (button) { button.disabled = true; button.textContent = 'Collecte en cours…'; }
        if (feedback) feedback.textContent = '';
        try {
            const response = await fetch(form.action || window.location.href, {
                method: 'POST',
                body: new FormData(form),
                headers: {'X-Requested-With': 'XMLHttpRequest'},
                credentials: 'same-origin'
            });
            if (!response.ok) throw new Error('HTTP ' + response.status);
            const result = await response.json();
            if (!result.success) throw new Error(result.message || 'Aucune donnée collectée');
            if (button) button.textContent = 'KPI actualisés ✓';
            if (feedback) feedback.textContent = ' ' + result.message + ' Publications manuelles et calendrier inclus.';
            window.setTimeout(() => { if (button) button.textContent = initialLabel; }, 3500);
        } catch (error) {
            if (feedback) feedback.textContent = ' Échec de la collecte. Réessayez.';
            if (button) button.textContent = initialLabel;
        } finally {
            if (button) button.disabled = false;
        }
    });
})();
</script>
